ls -l free_opt/xtbopt.xyz; grep -E 'GEOMETRY OPTIMIZATION CONVERGED|TOTAL ENERGY|total charge' free_opt/xtb.log | tail; python - <<'PY'
import pickle,numpy as np
from collections import Counter
m,a,rings,symbols=pickle.load(open('mols.pkl','rb'))
p=np.loadtxt('free_opt/xtbopt.xyz',skiprows=2,usecols=(1,2,3))
print('Composition:',dict(Counter(symbols)))
for mol,offset in [(m,0),(a,m.GetNumAtoms())]:
 for b in mol.GetBonds():
  i,j=b.GetBeginAtomIdx()+offset,b.GetEndAtomIdx()+offset
  d=np.linalg.norm(p[i]-p[j]); es={symbols[i],symbols[j]}
  if d>({'H':1.25}.get('H',1.25) if 'H' in es else (2.1 if 'Si' in es else 1.7)):
   print('Long bond:',i,j,d)
for r in rings:
 v=p[r]-p[r].mean(0); print('ring out-of-plane rms',np.linalg.svd(v)[1][-1]/np.sqrt(5))
with open('answer.xyz','w') as f:
 f.write(f'{len(symbols)}\nC34H55OSi2Ti; ethylene-bis(dimethylsilyl)-bridged tetramethylcyclopentadienyl Ti(III) adamantoxide; doublet\n')
 for s,v in zip(symbols,p):f.write(f'{s:2s} {v[0]: .8f} {v[1]: .8f} {v[2]: .8f}\n')
print('answer.xyz exists:',__import__('os').path.isfile('answer.xyz'))
PY
